head.script:

    scwin.onpageload = function() {
    };

    scwin.onpageunload = function() {

    };

    scwin.btn_onclick = function() {
        editor1.setDisabled(true);
        editor1.setDisabled(false);
        editor1.setDisabled(true);
    };


    scwin.editor1_onload = function() {
    };


	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById("editor1_disabled_div").getAttribute('hidden') === null;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn').click()");
		WebSquare.wUnit.addCommand("pause", "400");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
